 const middle=[['국어','수학','사회','음악','창체','체육'],['국어','수학','영어','과학','미술'],['국어','수학','사회','체육','도덕'],['국어','수학','영어','과학','창체'],['국어','수학','미술','음악','체육']];
 const high=[['국어','수학','사회','영어','창체','체육'],['국어','수학','영어','과학','미술','실과'],['국어','수학','사회','체육','도덕'],['국어','수학','영어','과학','창체','실과'],['국어','수학','미술','음악','체육','과학']];
 const starts=[540,590,640,690,790,840];const rows=(grade<3?low:grade<5?middle:high).map(day=>day.map((subject,i)=>({subject,start:starts[i],end:starts[i]+40,period:i+1,specialist:false})));
