 if(e.result&&(!Number.isInteger(e.result.voters)||e.result.voters<0||!Array.isArray(e.result.counts)||e.result.counts.some(c=>!ids.has(c.id)||!Number.isInteger(c.votes)||c.votes<0)||!Array.isArray(e.result.winners)||e.result.winners.some(id=>!ids.has(id))||!Number.isInteger(e.result.abstain)||e.result.abstain<0||e.result.counts.reduce((sum,c)=>sum+c.votes,e.result.abstain)!==e.result.voters))return false;return true;
