 const j=raw.journey;if(j){if(typeof j.id!=='string'||!ROOMS[j.from]||!['classroom','cafeteria','playground','gym'].includes(j.to)||!['lunch','pe','play','return','visit'].includes(j.purpose)||![0,1,2].includes(j.stage)||!['moving','arrived'].includes(j.status)||!Array.isArray(j.memberIds)||!j.memberIds.length||new Set(j.memberIds).size!==j.memberIds.length||j.memberIds.some(id=>!raw.students.some(s=>s.id===id))||!Array.isArray(j.arrivedIds))return false;if(j.status==='arrived'&&(j.stage!==2||raw.classLocation!==j.to||j.memberIds.some(id=>!j.arrivedIds.includes(id))))return false;}
